import AppKit

/// Watches the system clipboard. macOS has no "clipboard changed"
/// notification, so this checks the change counter a few times a second.
@MainActor
final class ClipboardMonitor {
    private let store: ClipboardStore
    private var timer: Timer?
    private var lastChangeCount: Int

    /// Markers that password managers and other apps put on items
    /// that shouldn't be kept (see nspasteboard.org).
    private static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
    ]

    init(store: ClipboardStore) {
        self.store = store
        lastChangeCount = NSPasteboard.general.changeCount
    }

    func start() {
        guard timer == nil else { return }
        // Don't record whatever was copied while the module was off.
        lastChangeCount = NSPasteboard.general.changeCount
        timer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.poll()
            }
        }
        timer?.tolerance = 0.1
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    /// Called after Toolbelt itself writes to the clipboard,
    /// so that write isn't recorded again as a new copy.
    func ignoreCurrentContents() {
        lastChangeCount = NSPasteboard.general.changeCount
    }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChangeCount else { return }
        lastChangeCount = pb.changeCount

        guard !Prefs.clipboardPaused else { return }

        let types = pb.types ?? []
        if types.contains(where: { Self.skipTypes.contains($0.rawValue) }) { return }

        let front = NSWorkspace.shared.frontmostApplication
        if let bundleID = front?.bundleIdentifier, Prefs.ignoredBundleIDs.contains(bundleID) { return }

        capture(from: pb, types: types, source: front)
    }

    private func capture(from pb: NSPasteboard, types: [NSPasteboard.PasteboardType], source: NSRunningApplication?) {
        let appName = source?.localizedName
        let bundleID = source?.bundleIdentifier

        // 1. Files copied in Finder
        if types.contains(.fileURL),
           let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let paths = urls.map(\.path)
            store.add(ClipItem(
                kind: .file,
                filePaths: paths,
                hash: Hashing.of("file:" + paths.joined(separator: "\n")),
                sourceAppName: appName,
                sourceBundleID: bundleID
            ))
            return
        }

        // 2. Text and links
        if let string = pb.string(forType: .string),
           !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            guard string.utf8.count < 2_000_000 else { return } // skip enormous copies
            var rtf: Data? = nil
            if let data = pb.data(forType: .rtf), data.count < 1_000_000 { rtf = data }
            store.add(ClipItem(
                kind: Self.isLink(string) ? .link : .text,
                text: string,
                rtf: rtf,
                hash: Hashing.of("text:" + string),
                sourceAppName: appName,
                sourceBundleID: bundleID
            ))
            return
        }

        // 3. Images and screenshots
        if let image = Self.pngData(from: pb) {
            guard image.png.count < 25_000_000 else { return }
            store.add(ClipItem(
                kind: .image,
                imageWidth: image.width,
                imageHeight: image.height,
                hash: Hashing.of(image.png),
                sourceAppName: appName,
                sourceBundleID: bundleID
            ), imageData: image.png)
        }
    }

    private static func isLink(_ string: String) -> Bool {
        let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.contains(where: { $0.isWhitespace }),
              let url = URL(string: trimmed),
              let scheme = url.scheme?.lowercased(),
              ["http", "https"].contains(scheme),
              url.host != nil else { return false }
        return true
    }

    private static func pngData(from pb: NSPasteboard) -> (png: Data, width: Int, height: Int)? {
        if let png = pb.data(forType: .png), let rep = NSBitmapImageRep(data: png) {
            return (png, rep.pixelsWide, rep.pixelsHigh)
        }
        guard let image = NSImage(pasteboard: pb),
              let tiff = image.tiffRepresentation,
              let rep = NSBitmapImageRep(data: tiff),
              let png = rep.representation(using: .png, properties: [:]) else { return nil }
        return (png, rep.pixelsWide, rep.pixelsHigh)
    }
}
